// Characterization tests: pin CURRENT behaviour of POST/GET /orders, quirks included.
import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { A: 10, B: 25.5, C: 0.1, D: 100, E: 100.5, F: 33.33, G: 1000 }
const pricing = { priceOf: async (sku) => prices[sku] }
let server, base

before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => server.close())

const post = (body) => fetch(`${base}/orders`, { method: 'POST', body: typeof body === 'string' ? body : JSON.stringify(body) })
const totalOf = async (items) => {
  const res = await post({ items })
  assert.equal(res.status, 201)
  return (await res.json()).total
}

test('total is sum of price*qty', async () => {
  assert.equal(await totalOf([{ sku: 'A', qty: 3 }, { sku: 'B', qty: 2 }]), 81)
})

test('total is floored (truncated), not rounded', async () => {
  assert.equal(await totalOf([{ sku: 'B', qty: 1 }]), 25) // 25.5
  assert.equal(await totalOf([{ sku: 'F', qty: 1 }]), 33) // 33.33
})

test('sub-euro totals floor to 0', async () => {
  assert.equal(await totalOf([{ sku: 'C', qty: 5 }]), 0)
})

test('no discount at exactly 100 (threshold is strictly > 100)', async () => {
  assert.equal(await totalOf([{ sku: 'D', qty: 1 }]), 100)
  assert.equal(await totalOf([{ sku: 'A', qty: 10 }]), 100)
})

test('10% discount applies just above threshold', async () => {
  assert.equal(await totalOf([{ sku: 'E', qty: 1 }]), 90) // 100.5 -> 90.45 -> 90
  assert.equal(await totalOf([{ sku: 'A', qty: 11 }]), 99) // 110 -> 99
})

test('larger orders: discount is a flat 10%, floored afterwards', async () => {
  assert.equal(await totalOf([{ sku: 'G', qty: 1 }]), 900)
  assert.equal(await totalOf([{ sku: 'G', qty: 10 }]), 9000)
  assert.equal(await totalOf([{ sku: 'F', qty: 7 }]), 209) // 233.31 -> 209.979 -> 209
})

test('discount applies to the whole order total, not per line', async () => {
  assert.equal(await totalOf([{ sku: 'A', qty: 6 }, { sku: 'A', qty: 6 }]), 108)
})

test('quirk: discounted order is cheaper than a slightly smaller undiscounted one', async () => {
  const at100 = await totalOf([{ sku: 'D', qty: 1 }])
  const above = await totalOf([{ sku: 'E', qty: 1 }])
  assert.ok(above < at100)
})

test('quirk: unknown sku / missing qty yields NaN total, serialised as null', async () => {
  const res = await post({ items: [{ sku: 'ZZZ', qty: 1 }] })
  assert.equal(res.status, 201)
  assert.equal((await res.json()).total, null)
})

test('quirk: negative qty is accepted and lowers total', async () => {
  assert.equal(await totalOf([{ sku: 'A', qty: -2 }]), -20)
})

test('created order is stored and retrievable with same total', async () => {
  const created = await (await post({ items: [{ sku: 'G', qty: 1 }] })).json()
  const res = await fetch(`${base}/orders/${created.id}`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), created)
})

test('validation: bad or empty input returns 400', async () => {
  for (const b of [{}, { items: [] }, { items: 'x' }, 'not json']) {
    const res = await post(b)
    assert.equal(res.status, 400)
    assert.deepEqual(await res.json(), { error: 'items required' })
  }
})

test('quirk: unknown order returns 200 with error body', async () => {
  const res = await fetch(`${base}/orders/does-not-exist`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), { error: 'not found' })
})

test('unknown route returns 404', async () => {
  const res = await fetch(`${base}/nope`)
  assert.equal(res.status, 404)
})
EOF
